ALTER TABLE public.profiles ADD COLUMN avatar jsonb;
CREATE TABLE public.player_live (session_id uuid NOT NULL REFERENCES public.sessions(id) ON DELETE CASCADE, user_id uuid NOT NULL, state jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(session_id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.player_live TO authenticated;
GRANT ALL ON public.player_live TO service_role;
ALTER TABLE public.player_live ENABLE ROW LEVEL SECURITY;
CREATE POLICY "members read live players" ON public.player_live FOR SELECT TO authenticated USING(public.is_member(session_id));
CREATE POLICY "members insert own live player" ON public.player_live FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.is_member(session_id));
CREATE POLICY "members update own live player" ON public.player_live FOR UPDATE TO authenticated USING(user_id=auth.uid() AND public.is_member(session_id)) WITH CHECK(user_id=auth.uid() AND public.is_member(session_id));
CREATE POLICY "members remove own live player" ON public.player_live FOR DELETE TO authenticated USING(user_id=auth.uid() AND public.is_member(session_id));
ALTER PUBLICATION supabase_realtime ADD TABLE public.player_live;
CREATE OR REPLACE FUNCTION public.join_session(_code text, _display text, _sprite int) RETURNS public.sessions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.sessions; n int; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not signed in'; END IF; SELECT * INTO s FROM public.sessions WHERE invite_code=upper(trim(_code)) AND mode='duo' FOR UPDATE; IF s.id IS NULL THEN RAISE EXCEPTION 'invite code not found'; END IF; IF EXISTS(SELECT 1 FROM public.session_members WHERE session_id=s.id AND user_id=auth.uid()) THEN RETURN s; END IF; SELECT count(*) INTO n FROM public.session_members WHERE session_id=s.id; IF n>=2 THEN RAISE EXCEPTION 'this town already has two players'; END IF; INSERT INTO public.session_members(session_id,user_id,role,display_name,sprite_index) VALUES(s.id,auth.uid(),'player2',_display,_sprite); RETURN s; END $$;
CREATE OR REPLACE FUNCTION public.add_xp(_sid uuid,_source text,_amount int,_cooldown_s int DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.sessions; amount int; cooldown int; key text; BEGIN IF NOT public.is_member(_sid) THEN RAISE EXCEPTION 'not a member'; END IF; SELECT * INTO s FROM public.sessions WHERE id=_sid FOR UPDATE;
IF _source LIKE 'npc:%' THEN amount:=10; cooldown:=315360000; key:='talkedTo'; ELSIF _source LIKE 'visit:%' THEN amount:=5; cooldown:=315360000; key:='visitedBuildings'; ELSIF _source='all-buildings' THEN amount:=25; cooldown:=315360000; IF jsonb_array_length(coalesce(s.world_state->'visitedBuildings','[]'))<10 THEN RAISE EXCEPTION 'visit all buildings first'; END IF; ELSIF _source LIKE 'seat:%' THEN amount:=5; cooldown:=300; ELSIF _source LIKE 'fish:%' THEN amount:=_amount; cooldown:=0; IF amount NOT IN(5,10,25) THEN RAISE EXCEPTION 'invalid fish reward'; END IF; ELSE RAISE EXCEPTION 'unknown XP source'; END IF;
IF EXISTS(SELECT 1 FROM public.xp_events WHERE session_id=_sid AND source=_source AND created_at>now()-make_interval(secs=>cooldown)) THEN RETURN jsonb_build_object('awarded',false,'xp',s.xp,'level',s.level); END IF;
INSERT INTO public.xp_events(session_id,user_id,source,amount) VALUES(_sid,auth.uid(),_source,amount);
UPDATE public.sessions SET xp=xp+amount,level=public.level_for_xp(xp+amount),updated_at=now(),world_state=CASE WHEN key IS NULL THEN world_state ELSE jsonb_set(world_state,ARRAY[key],coalesce(world_state->key,'[]')||to_jsonb(split_part(_source,':',2)),true) END WHERE id=_sid RETURNING * INTO s;
RETURN jsonb_build_object('awarded',true,'xp',s.xp,'level',s.level,'amount',amount); END $$;
CREATE OR REPLACE FUNCTION public.record_catch(_sid uuid,_catch jsonb,_xp int) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE reward int; r jsonb; BEGIN IF NOT public.is_member(_sid) THEN RAISE EXCEPTION 'not a member'; END IF; reward:=CASE _catch->>'id' WHEN 'minnow' THEN 5 WHEN 'bluegill' THEN 5 WHEN 'carp' THEN 5 WHEN 'perch' THEN 10 WHEN 'koi' THEN 10 WHEN 'duskeel' THEN 10 WHEN 'moonfish' THEN 25 WHEN 'goldkoi' THEN 25 ELSE NULL END; IF reward IS NULL THEN RAISE EXCEPTION 'unknown fish'; END IF; UPDATE public.sessions SET world_state=jsonb_set(world_state,'{fishCaught}',coalesce(world_state->'fishCaught','[]')||jsonb_build_array(_catch||jsonb_build_object('by',auth.uid(),'at',now())),true) WHERE id=_sid; r:=public.add_xp(_sid,'fish:'||(_catch->>'id'),reward,0); RETURN r; END $$;